// Tomamos el string HTML generado en el nodo anterior
const htmlString = $input.item.json.html_masivo;

// Construimos el archivo binario virtual
$input.item.binary = {
  html_file: {
    data: Buffer.from(htmlString).toString('base64'),
    mimeType: 'text/html',
    fileName: 'index.html' // Nombre innegociable para que Gotenberg lo lea
  }
};

return $input.item;
